<?php
namespace App\Services;use App\Models\Device;use App\Models\DeviceTemplate;use App\Models\User;use App\Services\Admin\DeviceAccessService;use Illuminate\Database\Eloquent\Builder;
class FleetService { private const SORTS=['name'=>'name','identifier'=>'external_id','status'=>'status','last_seen'=>'last_seen','created_at'=>'created_at'];public function __construct(private DeviceAccessService $access){}
 public function result(User $user,array $filters):array{$base=$this->access->accessibleDevices($user);$optionsBase=clone $base;$this->apply($base,$user,$filters);$summary=$this->summary(clone $base,$user);$sort=self::SORTS[$filters['sort']??'last_seen'];$direction=$filters['direction']??'desc';$page=$base->with(['template:id,name','canonicalLocation:id,name','accessAssignments'=>fn($q)=>$q->where('user_id',$user->id)->select('id','device_id','user_id','access_level')])->orderBy($sort,$direction)->orderBy('id')->paginate($filters['per_page']??25)->withQueryString();$templateIds=(clone $optionsBase)->whereNotNull('device_template_id')->distinct()->pluck('device_template_id');$templates=DeviceTemplate::query()->whereIn('id',$templateIds)->orderBy('name')->get(['id','name'])->map(fn($t)=>['id'=>(string)$t->id,'name'=>$t->name]);return compact('page','summary','templates');}
 private function apply(Builder $q,User $user,array $f):void{$q->when($f['search']??null,function($query,$value){$query->where(fn($n)=>$n->where('name','like',"%{$value}%")->orWhere('external_id','like',"%{$value}%")->orWhere('type','like',"%{$value}%")->orWhere('protocol','like',"%{$value}%")->orWhereHas('template',fn($t)=>$t->where('name','like',"%{$value}%")));})->when($f['status']??null,fn($x,$v)=>$x->where('status',$v))->when($f['device_template_id']??null,fn($x,$v)=>$x->where('device_template_id',$v))->when($f['device_type']??null,fn($x,$v)=>$x->where('type',$v))->when($f['protocol']??null,fn($x,$v)=>$x->where('protocol',$v))->when($f['location_id']??null,fn($x,$v)=>$x->where('location_id',$v));if(!empty($f['unassigned']))$q->whereNull('location_id');if(!$user->isPlatformAdmin()&&isset($f['access_level']))$q->whereHas('accessAssignments',fn($a)=>$a->where('user_id',$user->id)->where('access_level',$f['access_level']));}
 private function summary(Builder $q,User $user):array{$total=(clone $q)->count();$online=(clone $q)->where('status','online')->count();$full=$user->isPlatformAdmin()?$total:(clone $q)->whereHas('accessAssignments',fn($a)=>$a->where('user_id',$user->id)->where('access_level','full_access'))->count();$viewer=$user->isPlatformAdmin()?0:(clone $q)->whereHas('accessAssignments',fn($a)=>$a->where('user_id',$user->id)->where('access_level','viewer'))->count();return ['visibleDevices'=>$total,'online'=>$online,'offline'=>$total-$online,'fullAccess'=>$full,'viewer'=>$viewer,'templatesRepresented'=>(clone $q)->whereNotNull('device_template_id')->distinct()->count('device_template_id')];}}
